export const PHOTO_UPLOAD_SIGNER = Symbol('PHOTO_UPLOAD_SIGNER');

export interface SignPhotoUploadInput {
  /** Object key inside the bucket, e.g. `photos/2026/09/<uuid>.jpg` — generated by the service. */
  key: string;
  contentType: string;
  contentLength: number;
  expiresInSeconds: number;
  cacheControl: string;
}

export interface SignedPhotoUpload {
  uploadUrl: string;
  /**
   * Headers the browser MUST set on the PUT — each is part of the signature. The declared length
   * is signed as well but is not listed: the browser derives Content-Length from the body.
   */
  headers: Record<string, string>;
  expiresAt: Date;
}

/**
 * FR-CAT-10: presigns a direct browser → object-storage PUT for ONE key. Signing is local
 * computation (no network), so implementations must not connect at construction time
 * (docs/design/catalog/dress-photo-upload.md §2 R3).
 */
export interface PhotoUploadSignerPort {
  /** false = storage env missing → the use case answers 503 PHOTO.STORAGE_UNAVAILABLE. */
  isConfigured(): boolean;
  sign(input: SignPhotoUploadInput): Promise<SignedPhotoUpload>;
}
